}

fn supports_hyperlinks(&self) -> bool {
	use self::StandardStreamKind::*;

	match self.0 {
		LineBuffered(ref w) => w.supports_hyperlinks(),
		BlockBuffered(ref w) => w.supports_hyperlinks(),
