	}
}

fn is_synchronous(&self) -> bool {
	use self::StandardStreamKind::*;

	match self.0 {
		LineBuffered(ref w) => w.is_synchronous(),
		BlockBuffered(ref w) => w.is_synchronous(),
	}
}

fn features() -> Vec<String> {
	let mut features = vec![];

	let pcre2 = cfg!(feature = "pcre2");
	features.push(format!("{sign}pcre2", sign = sign(pcre2)));

	features
}

fn unwrap_switch(self) -> bool {
	match self {
		FlagValue::Switch(yes) => yes,
		FlagValue::Value(_) => {
			unreachable!("got flag value but expected switch")
		}
	}
}

fn unwrap_value(self) -> OsString {
	match self {
		FlagValue::Switch(_) => {
			unreachable!("got switch but expected flag value")
		}
		FlagValue::Value(v) => v,
	}
}

fn basename_for_regex(&self) -> &[u8] {
	// Literal basename strategies skip `..`, but a regex can match it.
	if self.basename.is_empty() && self.path.ends_with(b"..") {
		b".."
	} else {
		&self.basename
	}
}

fn matches_into(&self, path: &[u8], matches: &mut Vec<usize>) {
	if !self.may_match_length(path.len()) {
		return;
	}
	if let Some(hits) = self.literals.get(path) {
		matches.extend(hits);
	}
}

fn debug_impl_is_concise() {
	let set = build_glob_set(&["src/**/*.rs", "*.c"]);
	assert_eq!(
		format!("{:?}", set),
		r#"GlobSet([Glob("src/**/*.rs"), Glob("*.c")])"#
	);
	assert_eq!(format!("{:?}", GlobSet::empty()), "GlobSet([])");
}

fn matches_all_suffix() {
	let set = build_glob_set(&["*.rs", "*s", "*/main.rs"]);

	assert!(set.matches_all("a/b/c/main.rs"));

	assert!(!set.matches_all("foo.rs"));
	assert!(!set.matches_all("as"));
}

fn walk_unfiltered_parallel_12(b: &mut test::Bencher) {
	let ws = Workspace::new(128, 1, 32, false);
	let mut builder = ws.builder();
	builder.standard_filters(false);
	let expected = ws.python_files + 3;
	assert_eq!(walk(&builder, 12), expected);
	b.iter(|| assert_eq!(walk(black_box(&builder), 12), expected));
}

fn walk_explicit_files(b: &mut test::Bencher) {
	let ws = Workspace::new(64, 1, 8, false);
	let mut builder = WalkBuilder::from_iter(
		ws.paths.iter().map(|relative| ws.root.join(relative)),
	);
	builder.current_dir(&ws.root).hidden(false).git_global(false).threads(12);
	b.iter(|| assert_eq!(walk(black_box(&builder), 12), ws.python_files));
}

