}

fn errored_both() {
	let td = tmpdir();
	wfile(td.path().join(".gitignore"), "{foo");
	wfile(td.path().join(".ignore"), "{bar");

	let (_, err) = IgnoreBuilder::new().build().add_child(td.path());
	assert_eq!(2, partial(err.expect("an error")).len());
}

