}

impl ParallelVisitor for CountVisitor<'_> {
	fn visit(&mut self, entry: Result<DirEntry, Error>) -> WalkState {
		let entry = entry.unwrap();
		assert!(entry.error().is_none());
		self.count += usize::from(is_python(&entry));
		WalkState::Continue
	}
}

impl DirEntry {
