	fn try_from(bytes: Bytes) -> Result<Self, Self::Error> {
		Ok(Self(bytes.try_into()?))
	}
}

impl TryFrom<Vec<u8>> for Utf8Bytes {
	type Error = std::str::Utf8Error;

