		.max_jit_stack_size(Some(10 * (1 << 20)));
}

if args.quit_after_match() {
	WalkState::Quit
} else {
	match tx.send(haystack) {
		Ok(_) => WalkState::Continue,
		Err(_) => WalkState::Quit,
	}
}

if let Err(err) = print_thread.join().unwrap() {
	// A broken pipe means graceful termination, so fall through.
	// Otherwise, something bad happened while writing to stdout, so bubble
	// it up.
	if err.kind() != std::io::ErrorKind::BrokenPipe {
		return Err(err.into());
	}
}

if r.1 < r.0 {
	Err(Error {
		glob: Some(glob.to_string()),
		kind: ErrorKind::InvalidRange(r.0, r.1),
	})
} else {
	Ok(())
}

if let Some(class_ranges) = self.try_parse_posix_class() {
	ranges.extend(class_ranges);
	in_range = false;
} else {
	// Not a valid POSIX class, treat '[' as literal
	ranges.push(('[', '['));
	in_range = false;
}

if self.has_any_ignore_rules() {
	let mat = self.matched_ignore(path, is_dir);
	if mat.is_ignore() {
		return mat;
	} else if mat.is_whitelist() {
		whitelisted = mat;
	}
}

if is_dir {
	if !satisfies_min {
		mat = mat.not_within_depth();
	}
	if edge_max {
		mat = mat.no_descent();
	}
}

if matches.is_empty() {
	matches.push(caps.get(0).unwrap());
	matches.push(caps.get(1).unwrap());
	matches.push(caps.get(2).unwrap());
	Ok(true)
} else {
	Err(MyError)
}

if self.whole_line {
	singlepat = format!(r"(?m:^)(?:{})(?m:$)", singlepat);
} else if self.word {
	// We make this option exclusive with whole_line because when
	// whole_line is enabled, all matches necessary fall on word
	// boundaries. So this extra goop is strictly redundant.
	singlepat = format!(r"(?<!\w)(?:{})(?!\w)", singlepat);
}

if ch == '{' {
	State::OpenVariable
} else if ch == '}' {
	State::VerbatimCloseVariable
} else {
	builder.append_char(ch);
	State::Verbatim
}

if matches[midx].end() <= line.start() {
	if midx + 1 < matches.len() {
		midx += 1;
		continue;
	} else {
		break;
	}
}

if self.exceeds_max_columns(&bytes[this_line]) {
	self.write_exceeded_line(
		bytes, this_line, matches, &mut midx,
	)?;
} else {
	self.write_spec(spec, &bytes[this_line])?;
	self.write_line_term()?;
}

if cls.ranges().iter().map(|r| r.len()).sum::<usize>() == 1 {
	let contains = |r: &&ClassBytesRange| {
		r.start() <= byte && byte <= r.end()
	};
	if cls.ranges().iter().any(|r| contains(&r)) {
		return invalid();
	}
}

if !self.match_by_line_fast_invert(buf)? {
	// `match_by_line_fast_invert` returns `false` only
	// when a sink returned `false`. Stop entirely
	// instead of going on to the trailing
	// `after_context_by_line` below, which would call
	// the sink again for the same lines.
	return Ok(Stop);
}

if self.config.max_context() > 0 {
	if !self.after_context_by_line(buf, line.start())? {
		return Ok(Stop);
	}
	if !self.before_context_by_line(buf, line.start())? {
		return Ok(Stop);
	}
}

if !std::mem::replace(&mut self.data_written, true) {
	if self.event.flags.contains(EventFlags::HAS_DATA) {
		panic!("Called `Event::data*` multiple times");
	}

	let _ = buffer.write_str("data: ");
	self.event.flags.insert(EventFlags::HAS_DATA);
}

if let Some((kw, inner)) = b {
	if a.is_some() {
		let kw_name = std::any::type_name::<K>().split("::").last().unwrap();
		let msg = format!("`{kw_name}` specified more than once");
		return Err(syn::Error::new_spanned(kw, msg));
	}
	*a = Some((kw, inner));
}

if let Some(kw) = b {
	if a.is_some() {
		let kw_name = std::any::type_name::<K>().split("::").last().unwrap();
		let msg = format!("`{kw_name}` specified more than once");
		return Err(syn::Error::new_spanned(kw, msg));
	}
	*a = Some(kw);
}

if next_args.len() == 1 {
	let (idx, arg) = &next_args[0];
	if *idx != item_fn.sig.inputs.len() - 1 {
		return quote_spanned! {arg.span()=>
			compile_error!("`axum::middleware::Next` must be the last argument");
		};
	}
}

if value.is_empty() {
	return Err(syn::Error::new_spanned(
		path,
		"paths must start with a `/`. Use \"/\" for root routes",
	));
} else if !path.value().starts_with('/') {
	return Err(syn::Error::new_spanned(path, "paths must start with a `/`"));
}

if error.is::<tower::timeout::error::Elapsed>() {
	Ok(StatusCode::REQUEST_TIMEOUT)
} else {
	Err((
		StatusCode::INTERNAL_SERVER_ERROR,
		format!("Unhandled internal error: {error}"),
	))
}

if let Some(cf) = c {
	println!(
		">>> {who} got close with code {} and reason `{}`",
		cf.code, cf.reason
	);
} else {
	println!(">>> {who} somehow got close message without CloseFrame");
}

if let Some(cf) = c {
	println!(
		">>> {who} sent close with code {} and reason `{}`",
		cf.code, cf.reason
	);
} else {
	println!(">>> {who} somehow sent close message without CloseFrame");
}

for result in Walk::new("./") {
	// Each item yielded by the iterator is either a directory entry or an
	// error, so either print the path or the error.
	match result {
		Ok(entry) => println!("{}", entry.path().display()),
		Err(err) => println!("ERROR: {}", err),
	}
}

for result in self.regex.find_iter(haystack) {
	let m = result.map_err(Error::regex)?;
	match matched(Match::new(m.start(), m.end())) {
		Ok(true) => continue,
		Ok(false) => return Ok(Ok(())),
		Err(err) => return Ok(Err(err)),
	}
}

for &m in self.sunk.matches() {
	self.write_prelude(
		self.sunk.absolute_byte_offset() + m.start() as u64,
		self.sunk.line_number(),
		Some(m.start() as u64 + 1),
	)?;
	self.write_colored_line(&[m], self.sunk.bytes())?;
}

enum FlagLookup<'a> {
	/// Lookup found a match and the metadata for the flag is attached.
	Match(&'a FlagInfo),
