	Suffix { length: u64 },
}

match line.to_os_str() {
	Ok(osstr) => {
		args.push(osstr.to_os_string());
	}
	Err(err) => {
		errs.push(anyhow::anyhow!("{line_number}: {err}"));
	}
}

match builder.build() {
	Ok(gi) => {
		self.ig_builder.add_ignore(gi);
	}
	Err(err) => {
		errs.push(err);
	}
}

match cap_ref.cap {
	Ref::Number(i) => append(i, dst),
	Ref::Named(name) => {
		if let Some(i) = name_to_index(name) {
			append(i, dst);
		}
