}

match hyper::upgrade::on(req).await {
	Ok(upgraded) => {
		if let Err(e) = tunnel(upgraded, host_addr).await {
			tracing::warn!("server io error: {}", e);
		};
	}
	Err(e) => tracing::warn!("upgrade error: {}", e),
}

match res {
	Some(Ok(ws::Message::Text(s))) => {
		let _ = sender.send(s.to_string());
	}
	Some(Ok(_)) => {}
	Some(Err(e)) => tracing::debug!("client disconnected abruptly: {e}"),
	None => break,
}

while let Some(line) = stepper.next_match(buf) {
	if !self.sink_break_context(line.start())? {
		return Ok(false);
	}
	if !self.sink_before_context(buf, &line)? {
		return Ok(false);
	}
}

while curr < size {
	if bytes[curr] == b'/' && (bytes[curr + 1] == b'*' || bytes[curr + 1] == b':') {
		panic!(
			"You have a path with a deprecated format, move your ':var' or '*var' to '{{var}}'"
		);
	}
	curr += 1;
}

